// StatusOr<T> is a union of a Status object and a value of type T. It is used to
// encapsulate the result of an operation that may either succeed and produce a
// value of type T, or fail and produce a Status describing the error.
//
// A StatusOr in a successful state holds a value; a StatusOr in a failure state
// holds a non-OK Status.

#pragma once

#include <new>
#include <type_traits>
#include <utility>

#include "ray/common/status.h"
#include "ray/util/logging.h"

namespace ray {

template <typename T>
class StatusOr {
 public:
  // Default constructs the StatusOr with an unknown error status, i.e. it does
  // not hold a value.
  StatusOr() : status_(StatusCode::UnknownError, "Uninitialized StatusOr") {}

  // Implicitly constructible from a Status. The Status must not be OK, since an
  // OK status implies the presence of a value.
  StatusOr(const Status &status) : status_(status) {  // NOLINT
    RAY_CHECK(!status_.ok())
        << "Cannot construct a StatusOr with an OK status but no value.";
  }
  StatusOr(Status &&status) : status_(std::move(status)) {  // NOLINT
    RAY_CHECK(!status_.ok())
        << "Cannot construct a StatusOr with an OK status but no value.";
  }

  // Implicitly constructible from a value.
  StatusOr(const T &value) : status_(Status::OK()) {  // NOLINT
    new (&data_) T(value);
  }
  StatusOr(T &&value) : status_(Status::OK()) {  // NOLINT
    new (&data_) T(std::move(value));
  }

  StatusOr(const StatusOr &rhs) : status_(rhs.status_) {
    if (rhs.ok()) {
      new (&data_) T(rhs.value());
    }
  }
  StatusOr(StatusOr &&rhs) : status_(std::move(rhs.status_)) {
    if (ok()) {
      new (&data_) T(std::move(rhs.value()));
    }
  }

  // Allows implicit conversion from StatusOr<U> to StatusOr<T> as long as U is
  // convertible to T (e.g. from a derived type to a base type).
  template <typename U,
            typename = std::enable_if_t<std::is_convertible_v<U, T> &&
                                        !std::is_same_v<U, T>>>
  StatusOr(const StatusOr<U> &rhs) : status_(rhs.status()) {  // NOLINT
    if (rhs.ok()) {
      new (&data_) T(*rhs);
    }
  }
  template <typename U,
            typename = std::enable_if_t<std::is_convertible_v<U, T> &&
                                        !std::is_same_v<U, T>>>
  StatusOr(StatusOr<U> &&rhs) : status_(rhs.status()) {  // NOLINT
    if (rhs.ok()) {
      new (&data_) T(*std::move(rhs));
    }
  }

  StatusOr &operator=(const StatusOr &rhs) {
    if (this == &rhs) {
      return *this;
    }
    Clear();
    status_ = rhs.status_;
    if (rhs.ok()) {
      new (&data_) T(rhs.value());
    }
    return *this;
  }
  StatusOr &operator=(StatusOr &&rhs) {
    if (this == &rhs) {
      return *this;
    }
    Clear();
    status_ = std::move(rhs.status_);
    if (ok()) {
      new (&data_) T(std::move(rhs.value()));
    }
    return *this;
  }

  ~StatusOr() { Clear(); }

  // Returns true iff the StatusOr holds a value.
  bool ok() const { return status_.ok(); }
  explicit operator bool() const { return ok(); }

  // Returns the contained Status. If the StatusOr holds a value, the returned
  // status is OK.
  const Status &status() const { return status_; }

  // Returns the StatusCode of the contained Status.
  StatusCode code() const { return status_.code(); }

  // Returns a reference to the contained value. It is a fatal error to call this
  // if the StatusOr does not hold a value.
  T &value() & {
    RAY_CHECK(ok()) << "StatusOr has no value: " << status_.ToString();
    return *reinterpret_cast<T *>(&data_);
  }
  const T &value() const & {
    RAY_CHECK(ok()) << "StatusOr has no value: " << status_.ToString();
    return *reinterpret_cast<const T *>(&data_);
  }
  T &&value() && {
    RAY_CHECK(ok()) << "StatusOr has no value: " << status_.ToString();
    return std::move(*reinterpret_cast<T *>(&data_));
  }

  // Dereference operators. Behavior is undefined if the StatusOr does not hold a
  // value.
  T &operator*() & { return value(); }
  const T &operator*() const & { return value(); }
  T &&operator*() && { return std::move(*this).value(); }

  T *operator->() { return &value(); }
  const T *operator->() const { return &value(); }

  // Returns the contained value if ok, otherwise returns default_val.
  template <typename U>
  T value_or(U &&default_val) const & {
    if (ok()) {
      return value();
    }
    return static_cast<T>(std::forward<U>(default_val));
  }
  template <typename U>
  T value_or(U &&default_val) && {
    if (ok()) {
      return std::move(*this).value();
    }
    return static_cast<T>(std::forward<U>(default_val));
  }

  // Returns the contained value if ok, otherwise returns a default-constructed
  // T{}.
  T value_or_default() const & {
    if (ok()) {
      return value();
    }
    return T{};
  }
  T value_or_default() && {
    if (ok()) {
      return std::move(*this).value();
    }
    return T{};
  }

  // If this holds a value, invokes f with the value and returns its result;
  // otherwise returns the contained error status. f is expected to return a
  // StatusOr.
  template <typename F>
  auto and_then(F &&f) & {
    using Ret = std::invoke_result_t<F, T &>;
    if (ok()) {
      return std::forward<F>(f)(value());
    }
    return Ret(status_);
  }
  template <typename F>
  auto and_then(F &&f) const & {
    using Ret = std::invoke_result_t<F, const T &>;
    if (ok()) {
      return std::forward<F>(f)(value());
    }
    return Ret(status_);
  }
  template <typename F>
  auto and_then(F &&f) && {
    using Ret = std::invoke_result_t<F, T &&>;
    if (ok()) {
      return std::forward<F>(f)(std::move(*this).value());
    }
    return Ret(status_);
  }

  // If this holds a value, returns it; otherwise invokes f with the contained
  // error status and returns its result. f is expected to return a StatusOr.
  template <typename F>
  auto or_else(F &&f) & {
    if (ok()) {
      return StatusOr<T>(*this);
    }
    return StatusOr<T>(std::forward<F>(f)(status_));
  }
  template <typename F>
  auto or_else(F &&f) const & {
    if (ok()) {
      return StatusOr<T>(*this);
    }
    return StatusOr<T>(std::forward<F>(f)(status_));
  }
  template <typename F>
  auto or_else(F &&f) && {
    if (ok()) {
      return StatusOr<T>(std::move(*this));
    }
    return StatusOr<T>(std::forward<F>(f)(status_));
  }

  // Swaps the contents of this StatusOr with another.
  void swap(StatusOr &rhs) {
    if (this == &rhs) {
      return;
    }
    StatusOr tmp(std::move(*this));
    *this = std::move(rhs);
    rhs = std::move(tmp);
  }

 private:
  void Clear() {
    if (ok()) {
      reinterpret_cast<T *>(&data_)->~T();
    }
  }

  Status status_;
  // Aligned storage for the value; only holds a valid T when status_ is OK.
  alignas(T) unsigned char data_[sizeof(T)];
};

